# typed: strict
# frozen_string_literal: true

# Homebrew formula for deck-agent 0.1.0. Generated by scripts/package.ts; do not edit by hand.
class DeckAgent < Formula
  desc "Local agent host for nbg-design presentations"
  homepage "https://github.com/biks2013-tools/deck-agent"
  url "https://github.com/biks2013-tools/deck-agent/releases/download/v0.1.0/deck-agent-0.1.0.tar.gz"
  sha256 "6cecde1fecbbc6cb53af3182c3710db5475327043e2ea0a15ae757fb866f4bd9"

  depends_on "node"

  def install
    # The archive already holds the compiled code and its dependencies: nothing is built here.
    libexec.install Dir["*"]
    (bin/"deck-agent").write <<~SH
      #!/bin/bash
      exec "#{formula_opt_bin("node")}/node" "#{libexec}/dist/src/main.js" "$@"
    SH
  end

  service do
    run [opt_bin/"deck-agent", "serve"]
    keep_alive true
    environment_variables PATH: std_service_path_env
    log_path var/"log/deck-agent.log"
    error_log_path var/"log/deck-agent.log"
  end

  def caveats
    <<~EOS
      First-time setup:
        deck-agent init      writes ~/.tool-agents/deck-agent/.env with a generated access token
        (fill in the other settings; every one is required)
        deck-agent check     validates them

      Run the host in a terminal with "deck-agent serve", or in the background with
      "brew services start deck-agent". As a background service it does not see your
      shell's variables: put the model provider's API key in the .env file as well.

      The agent needs the nbg-design skill on this machine (DECK_AGENT_SKILL_DIR)
      and Google Chrome for checks and exports.
    EOS
  end

  test do
    assert_equal version.to_s, shell_output("#{bin}/deck-agent version").strip
  end
end
